import itertools, json
from problems import VertexCover, DominatingSet
from reduce import reduce as red

def vc_bruteforce(inst):
    n=inst['n']; edges=inst['edges']; k=inst['k']
    if k<0: return False
    for r in range(k+1):
        for subset in itertools.combinations(range(n), r):
            s=set(subset)
            if all(u in s or v in s for u,v in edges):
                return True
    return False

def ds_bruteforce(inst):
    n=inst['n']; edges=inst['edges']; k=inst['k']
    if k<0: return False
    if n==0: return True
    adj=[set([i]) for i in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    for r in range(k+1):
        for subset in itertools.combinations(range(n), r):
            dominated=set()
            for v in subset:
                dominated.update(adj[v])
            if len(dominated)==n:
                return True
    return False

def test():
    for n in range(0,5):
        verts=range(n)
        poss=[(u,v) for u in verts for v in verts if u<v]
        for mask in range(1<<len(poss)):
            edges=[[u,v] for i,(u,v) in enumerate(poss) if mask>>i &1]
            for k in range(-1,n+2):
                src={'n':n,'edges':edges,'k':k}
                try:
                    VertexCover.validate(src)
                except Exception:
                    continue
                src_ans=vc_bruteforce(src)
                tgt=red(src)
                tgt_ans=ds_bruteforce(tgt)
                if src_ans!=tgt_ans:
                    print('counterexample',src,tgt,src_ans,tgt_ans)
                    return False
    return True
print('result', test())
